'use strict';
(() => {
let filter='all';
function filterContent(){const host=document.querySelector('.collection-grid');if(!host)return;const cards=[...host.querySelectorAll('.content-card')],term=(document.getElementById('public-search')?.value||'').toLowerCase().trim();let count=0;for(const card of cards){card.hidden=!(card.textContent.toLowerCase().includes(term)&&(filter==='all'||card.dataset.access===filter));if(!card.hidden)count++;}document.getElementById('collection-count').textContent=`${count} ${count===1?'result':'results'}`;document.getElementById('search-empty').hidden=count!==0||!cards.length;}
function track(value){const application=value==='membership',extra=document.getElementById('membership-extra-fields');if(!extra)return;document.getElementById('application-track-type').value=application?'General Member Application':'Student Account';extra.hidden=!application;for(const id of ['university','interest','motivation'])document.getElementById('applicant-'+id).required=application;document.getElementById('applicant-motivation').minLength=20;document.getElementById('join-form-heading').textContent=application?'Become a society member':'Create a student account';document.getElementById('join-form-description').textContent=application?'Tell us how you would like to contribute. The team reviews each application.':'Start learning with the society.';document.getElementById('form-submit-btn').textContent=application?'Submit application':DSS.user?'Open your dashboard':'Create student account';document.querySelectorAll('[data-track]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.track===value)));}
function account(){const form=document.getElementById('join-form');if(!form||!DSS.user)return;const user=DSS.user,ambassador=form.dataset.ambassador==='true';if(['student','member'].includes(user.role)&&user.status==='approved'){document.getElementById('account-fields').hidden=true;document.querySelectorAll('#account-fields input').forEach(i=>i.disabled=true);for(const [key,value] of Object.entries(user.profile||{})){const el=document.getElementById('applicant-'+(key==='studentId'?'student-id':key));if(el&&!el.value)el.value=value;}if(!ambassador&&user.role==='student')track('membership');const application=ambassador?user.ambassadorApplication:user.membershipApplication;if(application?.status==='pending'){document.getElementById('join-feedback').textContent='Your application is under review. Follow its progress in your dashboard.';document.getElementById('form-submit-btn').disabled=true;}if(!ambassador&&user.role==='member')form.innerHTML='<a class="soc-button primary" href="member-dashboard.html">Open your member workspace</a>';}else form.innerHTML='<a class="soc-button primary" href="member-dashboard.html">Open your dashboard</a>';}
document.addEventListener('input',e=>{if(e.target.id==='public-search')filterContent();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-content-filter]');if(b){filter=b.dataset.contentFilter;document.querySelectorAll('[data-content-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});filterContent();}if(e.target.closest('[data-clear-search]')){document.getElementById('public-search').value='';document.querySelector('[data-content-filter="all"]').click();}const t=e.target.closest('[data-track]');if(t)track(t.dataset.track);});
document.addEventListener('dss:rendered',()=>{window.lucide?.createIcons();filterContent();account();});document.addEventListener('DOMContentLoaded',()=>{if(new URLSearchParams(location.search).get('track')==='membership')track('membership');window.lucide?.createIcons();});
})();
